# Generated by Phase: IMPLEMENT | Feature: EVOL-133
"""The session notebook — a long-lived session keeps its working state across a compaction (EVOL-133, #235).

The main session writes `.context/state/notebook/<name>.md`, with any tool:
  `## Standing` (the decisions in force, the queue, the user's words not yet acted on, all verbatim)
  then `## Log`, an append-only list of `- <UTC ISO> <text>` entries (continuation lines indented).

One reader, `gate.py notebook --hook-json`, dispatches on the hook payload's `hook_event_name`:
  PostToolUse       a write that lands directly in the notebook directory claims it for the session:
                    `.claude/state/notebook-{sid}.json` = {path, claimed_at, reload, unsaved, authors}, written to a
                    sibling temp file and moved with os.replace (no shared index, no lock; the last claim wins).
                    Edit / Write / MultiEdit, and a shell write resolved by the one write-target reader
                    (writes.targets, EVOL-065). A subagent's payload (`agent_id`) never claims.
  PreCompact        a claimed notebook is marked for reload; the user-authored transcript entries delivered after
                    the notebook's mtime are counted (authors only — never their words). A count above 0 prints an
                    advisory for the summary within budgets.notebook_precompact.
  UserPromptSubmit  a pending reload prints one <session-notebook> block within budgets.notebook_reinject: the
                    standing part whole, the newest log entries that fit, the cut pointer, the advisory line — then
                    clears the reload, so the block is consumed once. A standing part over the budget prints the
                    pointer only.

Every file is opened by open_single: O_NOFOLLOW + O_NONBLOCK, then fstat — a regular file with one link, under the
expected directory's realpath. Every path exits 0 (the caller wraps run() and swallows any fault): a notebook fault
never blocks a compaction or a prompt. Budgets are UTF-8 bytes; a cut never splits a log entry.
"""
from __future__ import annotations

import datetime
import json
import os
import re
import stat
import tempfile
from pathlib import Path

from . import writes
from .common import key

NB_DIR = Path(".context/state/notebook")
STATE_DIR = Path(".claude/state")
NAME = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]{0,127}\.md")
SID = re.compile(r"[A-Za-z0-9_-]{1,128}")
EDIT_TOOLS = {"Edit", "Write", "MultiEdit"}
AUTHORS = ("user", "queued", "peer", "other")
READ_MAX = 4 * 1024 * 1024            # a notebook or a state file larger than this is not ours to inject
TRANSCRIPT_MAX = 16 * 1024 * 1024     # the backwards scan stops here; the count is then a lower bound
CHUNK = 256 * 1024
LOG_HEAD = re.compile(r"(?m)^## Log[ \t]*$")
ENTRY = re.compile(r"^- ")
PEER = "<cross-session-message"
COMPACT_CMD = "<command-name>/compact</command-name>"
SKIP_PREFIX = "This session is being continued from a previous conversation"


class Refused(Exception):
    """A file the guard will not read: a link, a non-regular file, a second hard link, outside its directory."""


def open_single(path: Path, parent: Path | None = None, limit: int = READ_MAX) -> bytes:
    """The file's bytes — only a regular file with one link, opened without following a symlink, and (with
    `parent`) whose directory's realpath is `parent`'s. Anything else is Refused."""
    if parent is not None and os.path.realpath(path.parent) != os.path.realpath(parent):
        raise Refused(f"{path} is not directly under {parent}")
    try:
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    except OSError as e:
        raise Refused(f"{path}: {e.__class__.__name__}") from None
    try:
        st = os.fstat(fd)
        if not stat.S_ISREG(st.st_mode) or st.st_nlink != 1:
            raise Refused(f"{path} is not a regular file with one link")
        if st.st_size > limit:
            raise Refused(f"{path} is over {limit} bytes")
        chunks, left = [], limit + 1
        while left > 0:
            b = os.read(fd, min(left, CHUNK))
            if not b:
                break
            chunks.append(b)
            left -= len(b)
        return b"".join(chunks)
    finally:
        os.close(fd)


def _sid(payload: dict) -> str | None:
    sid = payload.get("session_id")
    return sid if isinstance(sid, str) and SID.fullmatch(sid) else None


def _state_path(repo: Path, sid: str) -> Path:
    return repo / STATE_DIR / f"notebook-{sid}.json"


def _read_state(repo: Path, sid: str) -> dict | None:
    p = _state_path(repo, sid)
    if not p.exists() and not p.is_symlink():
        return None
    st = json.loads(open_single(p, repo / STATE_DIR).decode("utf-8"))
    if not isinstance(st, dict) or not isinstance(st.get("path"), str):
        raise Refused("state file malformed")
    rel = Path(st["path"])
    if rel.parent != NB_DIR or not NAME.fullmatch(rel.name):
        raise Refused(f"state path {st['path']} is outside {NB_DIR}")
    return st


def _write_state(repo: Path, sid: str, st: dict) -> None:
    d = repo / STATE_DIR
    d.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=d, prefix=f".notebook-{sid}.", suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            json.dump(st, fh)
        os.replace(tmp, _state_path(repo, sid))
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


def _now() -> str:
    return datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


# ── PostToolUse: the claim ──────────────────────────────────────────────────────────────────────────────────────

def _written(repo: Path, payload: dict) -> list[str]:
    tool = payload.get("tool_name")
    ti = payload.get("tool_input") or {}
    if tool in EDIT_TOOLS:
        fp = ti.get("file_path") if isinstance(ti, dict) else None
        if not isinstance(fp, str) or not fp:
            return []
        p = Path(fp) if Path(fp).is_absolute() else repo / fp
        try:
            return [str(Path(os.path.abspath(p)).relative_to(repo))]
        except ValueError:
            return []
    if tool == "Bash":
        return list(writes.targets(repo, payload)["inside"])
    return []


def claim(repo: Path, payload: dict) -> str:
    sid = _sid(payload)
    if not sid or payload.get("agent_id"):
        return ""
    for rel in _written(repo, payload):
        r = Path(rel)
        if r.parent != NB_DIR or not NAME.fullmatch(r.name):
            continue
        open_single(repo / r, repo / NB_DIR)          # only a regular, single-link file under the directory is claimed
        try:
            old = _read_state(repo, sid) or {}
        except (Refused, ValueError):
            old = {}
        same = old.get("path") == str(r)
        _write_state(repo, sid, {"path": str(r), "claimed_at": _now(), "reload": bool(old.get("reload")) and same,
                                 "unsaved": old.get("unsaved", 0) if same else 0,
                                 "authors": old.get("authors", []) if same else []})
        return ""
    return ""


# ── PreCompact: reload + the unsaved count ──────────────────────────────────────────────────────────────────────

def _ts(entry: dict) -> float | None:
    t = entry.get("timestamp")
    if not isinstance(t, str):
        return None
    try:
        return datetime.datetime.fromisoformat(t.replace("Z", "+00:00")).timestamp()
    except ValueError:
        return None


def _text(content) -> str | None:
    """The entry's text; None when it carries a tool result (never a user's words)."""
    if isinstance(content, str):
        return content
    if not isinstance(content, list):
        return ""
    parts = []
    for b in content:
        if not isinstance(b, dict):
            continue
        if b.get("type") == "tool_result":
            return None
        if b.get("type") == "text" and isinstance(b.get("text"), str):
            parts.append(b["text"])
    return "\n".join(parts)


def author(entry: dict) -> str | None:
    """`user` (typed while idle), `queued` (typed mid-turn — judged at its delivery entry), `peer` (another
    session's message), `other` (a user entry we cannot classify); None for anything that is not someone's words."""
    t = entry.get("type")
    if t == "attachment":
        a = entry.get("attachment") or {}
        if not isinstance(a, dict) or a.get("type") != "queued_command":
            return None
        kind = (a.get("origin") or {}).get("kind") if isinstance(a.get("origin"), dict) else None
        prompt = a.get("prompt")
        text = prompt if isinstance(prompt, str) else (_text(prompt) or "")
        if kind == "human":
            return "queued"
        if kind == "peer" and PEER in text[:200]:
            return "peer"
        return None
    if t != "user" or entry.get("isCompactSummary") or entry.get("isSidechain"):
        return None
    text = _text((entry.get("message") or {}).get("content") if isinstance(entry.get("message"), dict) else None)
    if text is None:
        return None
    if PEER in text[:200]:
        return "peer"
    if entry.get("isMeta"):
        return None
    s = text.lstrip()
    if s.startswith("<command-name>"):
        return "user"
    if s.startswith("<") or s.startswith(SKIP_PREFIX):
        return None
    if not s and not isinstance((entry.get("message") or {}).get("content"), list):
        return "other"
    return "user"


def _backwards(path: Path):
    """Transcript entries from the end, newest first, within TRANSCRIPT_MAX bytes; yields (entry, capped)."""
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    try:
        st = os.fstat(fd)
        if not stat.S_ISREG(st.st_mode) or st.st_nlink != 1:
            raise Refused(f"{path} is not a regular file with one link")
        pos, read, tail = st.st_size, 0, b""
        while pos > 0 and read < TRANSCRIPT_MAX:
            n = min(CHUNK, pos, TRANSCRIPT_MAX - read)
            pos -= n
            read += n
            os.lseek(fd, pos, os.SEEK_SET)
            buf = os.read(fd, n) + tail
            lines = buf.split(b"\n")
            tail = lines[0] if pos > 0 else b""
            for line in reversed(lines[1:] if pos > 0 else lines):
                if line.strip():
                    try:
                        e = json.loads(line)
                    except ValueError:
                        continue
                    if isinstance(e, dict):
                        yield e, False
        if pos > 0:
            yield None, True
    finally:
        os.close(fd)


def unsaved(transcript: Path, since: float, manual: bool) -> tuple[int, list[str], bool]:
    """(count, authors, lower_bound): someone's words delivered after `since`. With a manual trigger the newest
    such entry that is the /compact invocation itself is not counted."""
    count, seen, capped, first = 0, [], False, True
    for e, cap in _backwards(transcript):
        if cap:
            capped = True
            break
        ts = _ts(e)
        if ts is not None and ts <= since:
            break
        who = author(e)
        if who is None:
            continue
        if first and manual:
            first = False
            text = _text((e.get("message") or {}).get("content")) if e.get("type") == "user" else ""
            if text and COMPACT_CMD in text:
                continue
        first = False
        count += 1
        if who not in seen:
            seen.append(who)
    return count, [a for a in AUTHORS if a in seen], capped


def _advisory_line(path: str, n: int, authors: list[str], capped: bool, resumed: bool = False) -> str:
    head = f"{'At least ' if capped else ''}{n} message(s) from {', '.join(authors) or 'other'} arrived after the notebook {path} was last written"
    if resumed:
        return head + " and before the compaction: take their requests and decisions from the summary and write them to the notebook now."
    return head + ". Keep the requests and decisions they carry in the summary, and write them to the notebook once the session resumes."


def precompact(repo: Path, payload: dict) -> str:
    sid = _sid(payload)
    if not sid:
        return ""
    st = _read_state(repo, sid)
    if st is None:
        return ""
    nb = repo / st["path"]
    open_single(nb, repo / NB_DIR)
    since = os.stat(nb, follow_symlinks=False).st_mtime
    n, authors, capped = 0, [], False
    tp = payload.get("transcript_path")
    if isinstance(tp, str) and tp:
        try:
            n, authors, capped = unsaved(Path(tp), since, payload.get("trigger") == "manual")
        except (OSError, Refused):
            n, authors, capped = 0, [], False
    st.update({"reload": True, "unsaved": n, "authors": authors, "lower_bound": capped})
    _write_state(repo, sid, st)
    if n <= 0:
        return ""
    budget = key(repo, "budgets.notebook_precompact", required=True)
    text = "<session-notebook-advisory>\n" + _advisory_line(st["path"], n, authors, capped) + "\n</session-notebook-advisory>"
    return text if len(text.encode()) <= int(budget) else ""


# ── UserPromptSubmit: the re-injection ──────────────────────────────────────────────────────────────────────────

def split(text: str) -> tuple[str, list[str]]:
    """(standing, log entries): everything above `## Log` is standing; below it, each entry starts at `- `."""
    m = LOG_HEAD.search(text)
    if not m:
        return text.rstrip("\n"), []
    standing, entries = text[:m.start()].rstrip("\n"), []
    for line in text[m.end():].split("\n"):
        if ENTRY.match(line):
            entries.append(line)
        elif entries and line.strip():
            entries[-1] += "\n" + line
    return standing, entries


def _esc(s: str) -> str:
    return s.replace("<", "&lt;")


def render(path: str, abspath: str, text: str, updated: str, budget: int, advisory: str = "") -> str:
    head = f'<session-notebook path="{path}" updated="{updated}">'
    tail = "</session-notebook>"
    adv = f"\n{advisory}" if advisory else ""
    standing, entries = split(_esc(text))
    pointer_only = (f"{head}\nThe notebook's standing part ({len(standing.encode())} bytes) is over the budget "
                    f"({budget} bytes). Read {abspath} whole now, before any other action.{adv}\n{tail}")
    fixed = f"{head}\n{standing}\n\n## Log{adv}\n{tail}"
    if len(fixed.encode()) > budget:
        return pointer_only if len(pointer_only.encode()) <= budget else ""
    kept: list[str] = []
    for i in range(len(entries) - 1, -1, -1):
        cut = i                                   # entries[:i] would be cut
        ptr = f"\n[{cut} older entries cut — read {abspath}]" if cut else ""
        body = "\n".join([entries[i]] + kept)
        if len(f"{head}\n{standing}\n\n## Log\n{body}{ptr}{adv}\n{tail}".encode()) > budget:
            break
        kept.insert(0, entries[i])
    cut = len(entries) - len(kept)
    ptr = f"\n[{cut} older entries cut — read {abspath}]" if cut else ""
    body = ("\n" + "\n".join(kept)) if kept else ""
    out = f"{head}\n{standing}\n\n## Log{body}{ptr}{adv}\n{tail}"
    if len(out.encode()) > budget:                  # the pointer alone did not fit beside the standing part
        return pointer_only if len(pointer_only.encode()) <= budget else ""
    return out


def reinject(repo: Path, payload: dict) -> str:
    sid = _sid(payload)
    if not sid:
        return ""
    st = _read_state(repo, sid)
    if not st or not st.get("reload"):
        return ""
    st["reload"] = False
    _write_state(repo, sid, st)                    # consumed once, before anything that could fail
    nb = repo / st["path"]
    text = open_single(nb, repo / NB_DIR).decode("utf-8", errors="replace")
    updated = datetime.datetime.fromtimestamp(os.stat(nb, follow_symlinks=False).st_mtime,
                                              datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    budget = int(key(repo, "budgets.notebook_reinject", required=True))
    n = st.get("unsaved", 0)
    adv = _advisory_line(st["path"], n, st.get("authors") or [], bool(st.get("lower_bound")), resumed=True) if isinstance(n, int) and n > 0 else ""
    return render(st["path"], str(nb), text, updated, budget, adv)


def run(repo: Path, payload: dict) -> str:
    """The one dispatch. The caller swallows every exception: a notebook fault prints nothing and exits 0."""
    if not isinstance(payload, dict):
        return ""
    event = payload.get("hook_event_name")
    if event == "PostToolUse":
        return claim(repo, payload)
    if event == "PreCompact":
        return precompact(repo, payload)
    if event == "UserPromptSubmit":
        return reinject(repo, payload)
    return ""
